SELECT gen_random_uuid()::text, 'formula', '$W = p\Delta V$', 'Constant-Pressure Process', '$W = p(V_2 - V_1) = mR(T_2 - T_1),\qquad Q = mc_p(T_2 - T_1)$', '$\text{kJ}$', 'Heating or cooling at fixed pressure (isobaric): the volume follows the temperature.', '[{"symbol":"$m$","meaning":"mass","unit":"$\\text{kg}$"},{"symbol":"$R$","meaning":"specific gas constant (air 0.287)","unit":"$\\text{kJ/(kg}\\cdot\\text{K)}$"},{"symbol":"$c_p$","meaning":"specific heat at constant pressure","unit":"$\\text{kJ/(kg}\\cdot\\text{K)}$"}]'::jsonb, '$\frac{V_2}{V_1} = \frac{T_2}{T_1}$ (Charles).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS' AND s."normKey" = 'processes of ideal gases' AND s."active"), NULL, false, 'PENDING', now(), now()
