SELECT gen_random_uuid()::text, 'formula', '$pV^k = C$', 'Isentropic Process', '$pV^k = C,\quad \frac{T_2}{T_1} = \left(\frac{p_2}{p_1}\right)^{\frac{k-1}{k}} = \left(\frac{V_1}{V_2}\right)^{k-1},\quad W = \frac{p_2V_2 - p_1V_1}{1 - k}$', '$\text{kJ}$', 'Reversible adiabatic: no heat, no friction; the ideal for turbines, compressors and nozzles.', '[{"symbol":"$k$","meaning":"ratio of specific heats, $c_p/c_v$ (1.4 for air)","unit":null},{"symbol":"$p, V, T$","meaning":"pressure, volume, absolute temperature","unit":null}]'::jsonb, 'Q = 0 and ΔS = 0; W = −ΔU = mc_v(T₁ − T₂).', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS' AND s."normKey" = 'processes of ideal gases' AND s."active"), NULL, false, 'PENDING', now(), now()
