SELECT gen_random_uuid()::text, 'formula', '$\Delta S$', 'Entropy Change of a Solid or Liquid', '$\Delta S = mc\ln\frac{T_2}{T_1}$', '$\text{kJ/K}$', 'Entropy change of an incompressible substance heated or cooled.', '[{"symbol":"$m$","meaning":"mass","unit":"$\\text{kg}$"},{"symbol":"$c$","meaning":"specific heat","unit":"$\\text{kJ/(kg}\\cdot\\text{K)}$"},{"symbol":"$T$","meaning":"absolute temperature","unit":"$\\text{K}$"}]'::jsonb, 'In a mixing problem the hot body loses entropy, the cold gains more: the total rises.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS' AND s."normKey" = 'second law and entropy' AND s."active"), NULL, false, 'PENDING', now(), now()
