SELECT gen_random_uuid()::text, 'formula', '$\frac{Q_H}{Q_L}$', 'Carnot Heat Ratio', '$\frac{Q_H}{Q_L} = \frac{T_H}{T_L}$', NULL, 'In a reversible cycle the heats are in the ratio of the absolute temperatures.', '[{"symbol":"$Q_H, Q_L$","meaning":"heat taken in and rejected","unit":"$\\text{kJ}$"},{"symbol":"$T_H, T_L$","meaning":"absolute temperatures of the hot and cold reservoirs","unit":"$\\text{K}$"}]'::jsonb, 'This is what defines the absolute temperature scale.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS' AND s."normKey" = 'carnot cycle' AND s."active"), NULL, true, 'PENDING', now(), now()
