SELECT gen_random_uuid()::text, 'formula', '$\eta_{Otto}$', 'Otto Cycle Efficiency', '$\eta_{Otto} = 1 - \frac{1}{r^{k-1}},\qquad r = \frac{V_1}{V_2}$', NULL, 'Ideal spark-ignition engine: heat added at constant volume.', '[{"symbol":"$r$","meaning":"compression ratio","unit":null},{"symbol":"$k$","meaning":"ratio of specific heats, $c_p/c_v$ (1.4 for air)","unit":null}]'::jsonb, 'r = 8, k = 1.4: 56.5%. Knock limits r in petrol engines.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS' AND s."normKey" = 'gas cycles (otto, diesel, brayton)' AND s."active"), NULL, true, 'PENDING', now(), now()
