SELECT gen_random_uuid()::text, 'formula', '$\eta_{Diesel}$', 'Diesel Cycle Efficiency', '$\eta_{Diesel} = 1 - \frac{1}{r^{k-1}}\cdot\frac{r_c^k - 1}{k(r_c - 1)},\qquad r_c = \frac{V_3}{V_2}$', NULL, 'Ideal compression-ignition engine: heat added at constant pressure.', '[{"symbol":"$r$","meaning":"compression ratio","unit":null},{"symbol":"$r_c$","meaning":"cutoff ratio","unit":null},{"symbol":"$k$","meaning":"ratio of specific heats, $c_p/c_v$ (1.4 for air)","unit":null}]'::jsonb, 'At the same r it is less efficient than Otto, but diesels run much higher r.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS' AND s."normKey" = 'gas cycles (otto, diesel, brayton)' AND s."active"), NULL, true, 'PENDING', now(), now()
