SELECT gen_random_uuid()::text, 'formula', '$\eta_{Brayton}$', 'Brayton Cycle Efficiency', '$\eta_{Brayton} = 1 - \frac{1}{r_p^{(k-1)/k}},\qquad r_p = \frac{p_2}{p_1}$', NULL, 'Ideal gas-turbine cycle: compression, constant-pressure heating, expansion.', '[{"symbol":"$r_p$","meaning":"pressure ratio","unit":null},{"symbol":"$k$","meaning":"ratio of specific heats, $c_p/c_v$ (1.4 for air)","unit":null}]'::jsonb, 'Back-work ratio $\frac{W_c}{W_t}$ is large (40–80%). For most net work, $r_p = \left(\frac{T_{\max}}{T_{\min}}\right)^{\frac{k}{2(k-1)}}$.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS' AND s."normKey" = 'gas cycles (otto, diesel, brayton)' AND s."active"), NULL, true, 'PENDING', now(), now()
