INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$\eta_{Rankine}$', 'Rankine Cycle Efficiency', '$\eta = \frac{(h_1 - h_2) - (h_4 - h_3)}{h_1 - h_4}$', NULL, 'The steam power plant cycle: pump, boiler, turbine, condenser.', '[{"symbol":"$h_1$","meaning":"turbine inlet","unit":"$\\text{kJ/kg}$"},{"symbol":"$h_2$","meaning":"turbine exit","unit":"$\\text{kJ/kg}$"},{"symbol":"$h_3$","meaning":"condenser exit (saturated liquid)","unit":"$\\text{kJ/kg}$"},{"symbol":"$h_4$","meaning":"pump exit","unit":"$\\text{kJ/kg}$"}]'::jsonb, 'Raise boiler pressure and superheat, or lower condenser pressure, to raise η.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS' AND s."normKey" = 'vapor cycles (rankine)' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$w_p$', 'Feed Pump Work', '$w_p = v_f(p_{high} - p_{low})$', '$\text{kJ/kg}$', 'The small work to pump liquid water up to boiler pressure.', '[{"symbol":"$v_f$","meaning":"specific volume of the liquid (≈ 0.001)","unit":"$\\text{m}^3\\text{/kg}$"},{"symbol":"$p$","meaning":"pressures","unit":"$\\text{kPa}$"}]'::jsonb, 'kPa × m³/kg = kJ/kg. Typically only 1–2% of the turbine work.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS' AND s."normKey" = 'vapor cycles (rankine)' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$SR$', 'Steam Rate', '$SR = \frac{3600}{w_{net}}\ \text{kg/kWh}$', NULL, 'Mass of steam needed per kilowatt-hour of net output.', '[{"symbol":"$w_{net}$","meaning":"net work per kg of steam","unit":"$\\text{kJ/kg}$"}]'::jsonb, 'With heat rate = 3600/η, the two numbers describe a plant''s performance.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS' AND s."normKey" = 'vapor cycles (rankine)' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
