SELECT gen_random_uuid()::text, 'formula', '$\eta_t$', 'Isentropic Efficiency of Turbines and Compressors', '$\eta_t = \frac{h_1 - h_2}{h_1 - h_{2s}},\qquad \eta_c = \frac{h_{2s} - h_1}{h_2 - h_1}$', NULL, 'How close a real turbine or compressor comes to the ideal.', '[{"symbol":"$h_{2s}$","meaning":"exit enthalpy for an isentropic process","unit":"$\\text{kJ/kg}$"},{"symbol":"$h$","meaning":"specific enthalpy","unit":"$\\text{kJ/kg}$"}]'::jsonb, 'The turbine''s actual work is LESS than ideal; the compressor''s needed work is MORE.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS' AND s."normKey" = 'vapor cycles (rankine)' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
