SELECT gen_random_uuid()::text, 'formula', '$y$', 'Open Feedwater Heater', '$y = \frac{h_{f,\,heater} - h_{in}}{h_{bleed} - h_{in}}$', NULL, 'In a regenerative cycle, the share of steam bled to heat the feedwater to saturation.', '[{"symbol":"$y$","meaning":"fraction of steam bled from the turbine","unit":null},{"symbol":"$h_{in}$","meaning":"enthalpy of the feedwater entering","unit":"$\\text{kJ/kg}$"},{"symbol":"$h_{bleed}$","meaning":"enthalpy of the bled steam","unit":"$\\text{kJ/kg}$"}]'::jsonb, 'Regeneration raises efficiency by heating the water nearer the boiler temperature.', 'ESAS', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS' AND s."normKey" = 'vapor cycles (rankine)' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Basic Thermodynamics' AND t."subject" = 'ESAS'
